checker_params.hidden_tests:
assert mod.word_frequencies('The cat and the hat.') == {'the': 2, 'cat': 1, 'and': 1, 'hat': 1}
assert mod.word_frequencies('') == {}
assert mod.word_frequencies("It's it, IT!") == {'it': 3, 's': 1}
assert mod.word_frequencies('a1b2a') == {'a': 2, 'b': 1}

items = list(range(0, 2000, 3))
for i, x in enumerate(items):
    assert mod.binary_search(items, x) == i
for x in (-3, 1, 2, 1999, 5000):
    assert mod.binary_search(items, x) == -1
assert mod.binary_search([], 4) == -1
